import React from 'react';

export function Checkbox({ label, checked = false }: { label: string; checked?: boolean }) {
  const [on, setOn] = React.useState(checked);
  return (
    <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '{{token:typography.scale.sm}}', color: '{{token:colors.text.primary}}' }}>
      <input type="checkbox" checked={on} onChange={(e) => setOn(e.target.checked)} aria-label={label}
        style={{ accentColor: '{{token:colors.accent.primary}}', width: '18px', height: '18px' }}
        onFocus={(e) => { e.currentTarget.style.outline = '2px solid {{token:colors.accent.primary}}'; e.currentTarget.style.outlineOffset = '2px'; }}
        onBlur={(e) => { e.currentTarget.style.outline = 'none'; }} />
      {label}
    </label>
  );
}
